using System; using System.Reflection;
class Probe { static int Main(string[] args) { try { var a=Assembly.LoadFrom(args[0]); Console.WriteLine(a.Location); var t=a.GetType("PAFPlayerScreenSaver.Poller"); byte[] raw=(byte[])t.GetMethod("Fetch").Invoke(null,new object[]{"http://127.0.0.1:666/api/screensaver/state",32768}); Console.WriteLine(System.Text.Encoding.UTF8.GetString(raw)); var st=a.GetType("PAFPlayerScreenSaver.State").GetMethod("Decode").Invoke(null,new object[]{raw}); Console.WriteLine("Online="+st.GetType().GetField("Online").GetValue(st)); return 0; } catch(Exception e) { Console.WriteLine(e); return 1; } } }